namespace docking.widgets.dialogs;

using static org.junit.Assert;

using org.junit;

/**
 * {@link NumberInputDialog} test. 
 * 
 * <p>Note: most of the tests for the base class are in {@link BigIntegerNumberInputDialogTest}.
 */
public class NumberInputDialogTest : AbstractNumberInputDialogTest {

	/* @Test */
	public void testTypeIntTooBigWithOverflow() {
		int initial = 2;
		createAndShowDialog(initial, 0, int.MaxValue);

		string okInt = "500000000";
		setText(okInt);
		assertTrue(okButton.isEnabled());

		setText(okInt + "0");
		assertEquals("Value must be between 0 and " + int.MaxValue, dialog.getStatusText());

		setText(okInt + "00");
		assertEquals("Value must be between 0 and " + int.MaxValue, dialog.getStatusText());

		setText(okInt + "000");
		assertEquals("Value must be between 0 and " + int.MaxValue, dialog.getStatusText());

		int valid = int.MaxValue - 1;
		setText(Integer.toString(valid));
		oK();
		assertEquals(valid, getValue());
	}

	private int getValue() {
		return ((NumberInputDialog) dialog).getValue();
	}
}
